from functools import reduce
from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The puzzle is a periodic tiled board. Its long, mostly uniform rails carry
    # the corner symbols; use rails with several exceptional cells as vertices.
    rail_rows = []
    rail_base = {}
    for r, row in enumerate(grid):
        color, count = Counter(row).most_common(1)[0]
        if count / w >= 0.74 and count < w:
            rail_rows.append(r)
            rail_base[r] = color
    if len(rail_rows) < 2:
        return [row[:] for row in grid]

    changed_cols = sorted({c for r in rail_rows for c, value in enumerate(grid[r])
                           if value != rail_base[r]})
    if len(changed_cols) < 2:
        return [row[:] for row in grid]

    row_steps = [b - a for a, b in zip(rail_rows, rail_rows[1:])]
    col_steps = [b - a for a, b in zip(changed_cols, changed_cols[1:])]
    row_step = reduce(gcd, row_steps)
    col_step = reduce(gcd, col_steps)
    if row_step <= 0 or col_step <= 0:
        return [row[:] for row in grid]

    # Extend the sparse changed rail intersections to the regular vertex lattice;
    # unchanged vertices are meaningful and must remain in the extracted pattern.
    rows = list(range(rail_rows[0], rail_rows[-1] + 1, row_step))
    cols = list(range(changed_cols[0], changed_cols[-1] + 1, col_step))
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = []
    for ri in range(len(rows) - 1):
        out_row = []
        for ci in range(len(cols) - 1):
            a, b = grid[rows[ri]][cols[ci]], grid[rows[ri]][cols[ci + 1]]
            c, d = grid[rows[ri + 1]][cols[ci]], grid[rows[ri + 1]][cols[ci + 1]]
            out_row.append(a if a == b == c == d else background)
        out.append(out_row)
    return out


